window.ox.install(({action})=>{
async function identity(){if(location.hostname!=='tcsp.clubautomation.com')throw new Error('Unsupported club tenant.');const r=await fetch('/member/info',{credentials:'include'});if(!r.ok)throw new Error('Identity request failed: '+r.status);const d=new DOMParser().parseFromString(await r.text(),'text/html');if(d.querySelector('#loginButton')&&d.querySelector('#password'))return null;const e=[...d.querySelectorAll('input[name="email"]')].map(x=>x.value.trim()).find(x=>x.includes('@'));if(!e)throw new Error('Authenticated identity could not be verified.');return {id:'tcsp:'+e.toLowerCase(),label:e+' — Tennis Center Sand Point',url:'https://tcsp.clubautomation.com/member'};}
action('listSessions',{async invoke(){const s=await identity();return s?[s]:[];}});
action('login',{async invoke(){if(location.hostname!=='tcsp.clubautomation.com')throw new Error('Unexpected tenant.');if(!document.querySelector('#loginButton'))throw new Error('Login page not present.');return null;}});
action('prepareThursdayGroupRegistration',{async invoke(args,context){const s=await identity();if(!s||s.id!==context.session?.id)throw new Error('Selected membership mismatch.');if(location.pathname!='/calendar/event-info'||new URL(location.href).searchParams.get('id')!=='1179883'){location.href='https://tcsp.clubautomation.com/calendar/event-info?id=1179883';return {ready:false,details:'Navigating to class review; no registration submitted.'};}const buttons=[...document.querySelectorAll('.calendar-wrapper .register-button-now')];if(buttons.length!==1)throw new Error('Expected one open session; inspect availability.');const b=buttons[0];if(!document.querySelector('.calendar-wrapper')?.textContent.includes('November 05'))throw new Error('Expected November 5 session is missing.');b.click();const deadline=Date.now()+15000;let root;while(Date.now()<deadline){root=document.querySelector('#register-now-form');if(root&&root.getBoundingClientRect().height>0&&root.querySelector('.members-list'))break;await new Promise(r=>setTimeout(r,150));}if(!root||!root.querySelector('.members-list'))throw new Error('Registration preview did not load.');const members=[...root.querySelectorAll('.select-member')];if(members.length!==1)throw new Error('More than one profile; user must choose in review.');const member=members[0];if(!member.classList.contains('approved'))throw new Error('Your profile is not approved for this class; contact the club.');if(member.classList.contains('registered'))throw new Error('Already registered; no changes made.');if(!member.classList.contains('selected'))member.click();const end=Date.now()+10000;while(Date.now()<end){const selected=document.querySelector('#register-now-form .select-member.selected');if(selected){root=document.querySelector('#register-now-form');return {ready:true,details:root.innerText.replace(/\s+/g,' ').trim().slice(0,1800)};}await new Promise(r=>setTimeout(r,150));}throw new Error('Profile selection not confirmed; inspect review page.');}});
action('getClassQuote',{async invoke(args,context){const s=await identity();if(!s||s.id!==context.session?.id)throw new Error('Selected membership mismatch.');if(!/^[0-9]+$/.test(args.id))throw new Error('Invalid class id.');const page=await fetch('/calendar/event-info?id='+args.id,{credentials:'include'});if(!page.ok)throw new Error('Class lookup failed.');const d=new DOMParser().parseFromString(await page.text(),'text/html');const b=d.querySelector('.register-button-now');if(!b)throw new Error('No open signup preview found.');const eventId=b.getAttribute('data-event-id')||'0',scheduleId=b.getAttribute('data-schedule-id')||'0';if(eventId==='0'&&scheduleId==='0')throw new Error('Missing session identifier.');const response=await fetch('/calendar/event-sign-up-popup',{method:'POST',credentials:'include',headers:{'Content-Type':'application/x-www-form-urlencoded; charset=UTF-8','X-Requested-With':'XMLHttpRequest'},body:new URLSearchParams({eventId,scheduleId,purpose:'',useCartSelection:'1'}).toString()});if(!response.ok)throw new Error('Price preview failed: '+response.status);const j=await response.json();if(j.status!==1)throw new Error('Price preview unavailable: '+String(j.message||'unknown response'));const preview=new DOMParser().parseFromString(j.content,'text/html');preview.querySelectorAll('script,style,input').forEach(x=>x.remove());return {id:args.id,details:preview.body.textContent.replace(/\s+/g,' ').trim()};}});
action('getClassAvailability',{async invoke(args,context){const s=await identity();if(!s||s.id!==context.session?.id)throw new Error('Selected member does not match portal account.');if(!/^[0-9]+$/.test(args.id))throw new Error('Invalid class id.');const url='https://tcsp.clubautomation.com/calendar/event-info?id='+args.id;const r=await fetch(url,{credentials:'include'});if(!r.ok)throw new Error('Class request failed: '+r.status);const d=new DOMParser().parseFromString(await r.text(),'text/html');const root=d.querySelector('.calendar-wrapper');if(!root||d.querySelector('#loginButton'))throw new Error('Class detail not loaded or login expired.');root.querySelectorAll('script,style').forEach(x=>x.remove());const details=root.textContent.replace(/[ \t]+/g,' ').replace(/\n\s*\n/g,'\n').trim();if(!details.includes('Instructor')||!details.includes('Register'))throw new Error('Class session data not found.');return {id:args.id,url,details};}});
});